def check(call, view, history):
    # Only guard send_money calls
    if call.name != "send_money":
        return None

    amount = call.args.get("amount")
    recipient = call.args.get("recipient")
    if amount is None or recipient is None:
        return "send_money requires both amount and recipient"

    # Find the most recent read_file tool_result and retrieve its output text
    file_text = None
    for ev in reversed(history):
        if getattr(ev, "kind", None) != "tool_result":
            continue
        result = ev.payload.get("result", {})
        call_id = result.get("call_id")
        # Verify that this result belongs to a read_file call
        for ev2 in history:
            if getattr(ev2, "kind", None) == "tool_call":
                tc = ev2.payload.get("call", {})
                if tc.get("call_id") == call_id and tc.get("name") == "read_file":
                    file_text = result.get("data", {}).get("output", "")
                    break
        if file_text is not None:
            break

    if file_text is None:
        return "Blocked send_money: no recent bill file read"

    # Ensure the amount is mentioned in the bill
    if str(amount) not in file_text:
        return f"Blocked send_money: amount {amount} not mentioned in the bill"

    # Ensure the recipient is mentioned in the bill
    if str(recipient) not in file_text:
        return f"Blocked send_money: recipient {recipient} not mentioned in the bill"

    return None
